<section class="page-head"><div><div class="eyebrow">REPORTS / ANALYTICS</div><h1>گزارشات</h1><p>فروش، پرداخت‌ها، عملکرد روزانه و پرفروش‌ترین محصولات را تحلیل کنید.</p></div></section>
<form class="card toolbar report-filter"><div class="filters"><label>از <input class="field" type="date" name="from" value="<?=htmlspecialchars($from)?>"></label><label>تا <input class="field" type="date" name="to" value="<?=htmlspecialchars($to)?>"></label><label>وضعیت <select class="field" name="status"><option value="completed" <?=$status==='completed'?'selected':''?>>تکمیل‌شده</option><option value="all" <?=$status==='all'?'selected':''?>>همه</option></select></label><button class="btn btn-primary">اعمال فیلتر</button></div></form>
<div class="grid kpi-grid report-kpis"><div class="card stat-card"><div class="stat-top"><span>فروش</span><span class="stat-icon">↗</span></div><div class="stat-value"><?=number_format((float)($summary['sales']??0))?></div><div class="stat-meta">ریال</div></div><div class="card stat-card"><div class="stat-top"><span>تعداد سفارش</span><span class="stat-icon">▤</span></div><div class="stat-value"><?=number_format((int)($summary['order_count']??0))?></div></div><div class="card stat-card"><div class="stat-top"><span>میانگین سفارش</span><span class="stat-icon">◈</span></div><div class="stat-value"><?=number_format((float)($summary['avg_order']??0))?></div><div class="stat-meta">ریال</div></div><div class="card stat-card"><div class="stat-top"><span>پرداخت‌شده</span><span class="stat-icon">✓</span></div><div class="stat-value"><?=number_format((float)($summary['paid']??0))?></div><div class="stat-meta">ریال</div></div></div>
<div class="grid dashboard-grid"><section class="card section-card"><div class="card-head"><h2>فروش روزانه</h2></div><div class="table-wrap"><table><thead><tr><th>تاریخ</th><th>سفارش</th><th>فروش</th></tr></thead><tbody><?php foreach($daily as $r): ?><tr><td><?=htmlspecialchars($r['day'])?></td><td><?=number_format($r['orders'])?></td><td><?=number_format($r['amount'])?> ریال</td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card section-card"><div class="card-head"><h2>روش‌های پرداخت</h2></div><div class="table-wrap"><table><thead><tr><th>روش</th><th>تعداد</th><th>مبلغ</th></tr></thead><tbody><?php foreach($payments as $r): ?><tr><td><?=htmlspecialchars($r['payment_method']??'—')?></td><td><?=number_format($r['orders'])?></td><td><?=number_format($r['amount'])?> ریال</td></tr><?php endforeach; ?></tbody></table></div></section></div>
<section class="card section-card report-section"><div class="card-head"><h2>پرفروش‌ترین محصولات</h2><small>۲۰ محصول برتر</small></div><div class="table-wrap"><table><thead><tr><th>محصول</th><th>تعداد</th><th>فروش</th></tr></thead><tbody><?php foreach($products as $r): ?><tr><td><strong><?=htmlspecialchars($r['name'])?></strong></td><td><?=number_format((float)$r['qty'],3)?></td><td><?=number_format((float)$r['amount'])?> ریال</td></tr><?php endforeach; ?></tbody></table></div></section>